function sumNumbers(arr) {
  let total = 0;
  for (let i = 0; i < arr.length; i++) {
    total += arr[i]; // TurboFan assumes arr[i] is Smi or double
  }
  return total;
}

// Warm up — triggers optimization
for (let n = 0; n < 100_000; n++) sumNumbers([1, 2, 3]);

function add(a, b) {
  return a + b;
}

for (let i = 0; i < 50_000; i++) add(1, 2);     // optimized for numbers
add('1', '2'); // still works — but may deopt if +' was specialized

